import React from 'react';
import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';
import { useWishlist } from '../../context/WishlistContext';
import { formatPrice, renderStars } from '../../utils/helpers';

const Wishlist = () => {
  const { wishlist, removeFromWishlist } = useWishlist();

  return (
    <div>
      <div className="page-hero">
        <div className="container">
          <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }}>
            <h1>My Wishlist</h1>
            <p>{wishlist.length} destination{wishlist.length !== 1 ? 's' : ''} saved</p>
          </motion.div>
        </div>
      </div>

      <div className="container section-padding">
        {wishlist.length === 0 ? (
          <div className="empty-state">
            <i className="bi bi-heart"></i>
            <h5>Your wishlist is empty</h5>
            <p>Start exploring and save your dream destinations!</p>
            <Link to="/destinations" className="btn btn-teal mt-3">Explore Destinations</Link>
          </div>
        ) : (
          <div className="row g-4">
            {wishlist.map((dest, i) => (
              <div key={dest.id} className="col-md-6 col-lg-4">
                <motion.div initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: i * 0.08 }} whileHover={{ y: -6 }} className="card-premium h-100">
                  <div style={{ position: 'relative', overflow: 'hidden' }}>
                    <img src={dest.image} alt={dest.title} style={{ width: '100%', height: 200, objectFit: 'cover', transition: 'transform 0.4s' }}
                      onMouseEnter={e => e.target.style.transform = 'scale(1.05)'}
                      onMouseLeave={e => e.target.style.transform = 'scale(1)'} />
                    <button onClick={() => removeFromWishlist(dest.id)}
                      style={{ position: 'absolute', top: 12, right: 12, width: 36, height: 36, borderRadius: '50%', background: 'white', border: 'none', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', boxShadow: '0 2px 8px rgba(0,0,0,0.15)' }}>
                      <i className="bi bi-heart-fill" style={{ color: '#e74c3c' }}></i>
                    </button>
                    <span className="badge-teal" style={{ position: 'absolute', bottom: 12, left: 12 }}>{dest.category}</span>
                  </div>
                  <div className="p-3">
                    <h6 style={{ fontFamily: 'Poppins', fontWeight: 700, marginBottom: 4 }}>{dest.title}</h6>
                    <p style={{ color: '#666', fontSize: '0.82rem', marginBottom: 10 }}>
                      <i className="bi bi-geo-alt-fill me-1" style={{ color: '#307082' }}></i>{dest.location}
                    </p>
                    <div className="d-flex align-items-center justify-content-between">
                      <div>
                        <div className="star-rating mb-1">
                          {renderStars(dest.rating).map((cls, i) => <i key={i} className={`bi ${cls}`}></i>)}
                        </div>
                        <div className="price-tag">{formatPrice(dest.price)}<span>/person</span></div>
                      </div>
                      <Link to={`/destinations/${dest.id}`} className="btn btn-teal btn-sm">Explore</Link>
                    </div>
                  </div>
                </motion.div>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

export default Wishlist;
